import {sourceLibrary,domainMap} from './advanced.js';
import {modules,lessonCount} from './content.js';
const root=document.querySelector('#app');
import {kind,canCheck,createSession,checkAttempt,advance,migrate,nextLesson,inTier} from './learning.js';
let saved;try{saved=JSON.parse(localStorage.getItem('curd-v1'));}catch{}
let state=migrate(saved,modules);
let view='learn',activeModule=Number((nextLesson(modules,state.done,state.tier)||'0-0').split('-')[0]),session=null,notice='';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
function save(){try{localStorage.setItem('curd-v1',JSON.stringify(state));}catch{notice='Storage is unavailable. Your progress will last only for this visit.';}}
function streak(){let d=new Date();let count=0;if(!state.days.includes(today()))d.setDate(d.getDate()-1);while(state.days.includes(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`)){count++;d.setDate(d.getDate()-1);}return count;}
const paths={learn:'M5 5h6v15H5zM13 5h6v15h-6',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',cheese:'M3 10 15 3l6 7v11H3zM3 10h18M8 14h.1M15 17h.1',milk:'M8 3h8v5l3 4v9H5v-9l3-4zM8 7h8M5 13h14',clock:'M12 7v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',box:'m3 7 9-4 9 4v13H3zM3 7l9 5 9-5M12 12v8',chat:'M3 4h18v13H9l-6 4z',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M2 12h20M12 2c-6 6-6 14 0 20 6-6 6-14 0-20',shield:'m12 3 9 4v6c0 5-9 9-9 9s-9-4-9-9V7z',journal:'M5 3h14v18H5zM8 8h8M8 12h8M8 16h5',check:'m5 12 5 5L20 7',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5z',arrow:'M5 12h14m-5-5 5 5-5 5',fire:'M12 2c3 5-2 6 3 10 2-1 3-3 3-3 7 10-2 15-8 12C1 18 5 11 8 8c-1 5 4 5 4-6'};
const icon=(n,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.star}"/></svg>`;
const mascot=`<svg class="mascot" viewBox="0 0 240 210" aria-hidden="true"><ellipse cx="121" cy="188" rx="65" ry="8" fill="#e7e0c8"/><path d="M49 78 155 35l48 49v79c-37 18-101 22-154 0Z" fill="#f0c85e" stroke="#55482d" stroke-width="3"/><path d="M49 78c41 11 99 12 154 6l-48-49Z" fill="#ffe69b" stroke="#55482d" stroke-width="3"/><path d="M49 78v85c48 17 109 18 154 0V84" fill="none" stroke="#55482d" stroke-width="3"/><ellipse cx="88" cy="68" rx="12" ry="5" fill="#d3a83e"/><ellipse cx="145" cy="62" rx="9" ry="5" fill="#d3a83e"/><circle cx="71" cy="111" r="8" fill="#dcb148"/><circle cx="181" cy="147" r="10" fill="#dcb148"/><circle cx="83" cy="153" r="5" fill="#dcb148"/><path d="M108 113v8m39-8v8m-33 15q12 13 25-1" stroke="#55482d" stroke-width="5" stroke-linecap="round" fill="none"/><path d="m51 129-20-13m172 6 17-19M90 175l-4 13m69-13 4 13" stroke="#55482d" stroke-width="4" stroke-linecap="round"/><path d="m29 105 2 11-11-1m197-23 3 11 10-4" fill="none" stroke="#55482d" stroke-width="3" stroke-linecap="round"/></svg>`;
function nav(){return [['learn','Learn','learn'],['practice','Practice','star'],['journal','Tasting journal','journal']].map(([v,t,i])=>`<button class="nav-item ${view===v?'active':''}" data-view="${v}">${icon(i)}<span>${t}</span></button>`).join('');}
function render(){if(session){renderLesson();return;}root.innerHTML=`<aside class="sidebar"><a class="brand" href="#" aria-label="Curd home">${icon('cheese')}curd</a><div class="brand-note">A LITTLE KNOWLEDGE. DAILY.</div><nav aria-label="Main navigation">${nav()}</nav><div class="sidebar-bottom"><span class="level-mark">${Math.floor(state.done.length/3)+1}</span><div>Cheese curious<br><small>${state.done.length} / ${lessonCount} lessons explored.</small></div></div></aside><div class="shell"><header><span>YOUR DAILY CHEESE SCHOOL</span><div class="stats"><span title="Consecutive study days">${icon('fire')} ${streak()} <small>day streak</small></span><span>${icon('star')} ${state.xp} <small>XP</small></span><div class="avatar">C</div></div></header><main>${notice?`<p role="status">${esc(notice)}</p>`:''}${view==='learn'?learn():view==='practice'?practice():journal()}</main><footer>Made for the love of cheese. <a href="https://academyofcheese.org/study-cheese/associate/" target="_blank" rel="noreferrer">Course inspiration ↗</a><span>Independent study aid · Unofficial practice content</span></footer></div><nav class="mobile-nav" aria-label="Mobile navigation">${nav()}</nav>`;bind();}
const tierLessons=mi=>modules[mi].lessons.map((l,i)=>({l,i})).filter(({l})=>inTier(l,state.tier));
function references(refs=[]){if(!refs.length)return '';return `<details class="course-sources"><summary>Study references</summary>${refs.map(r=>{const a=sourceLibrary[r.source];return `<p><strong>${a.url?`<a href="${esc(a.url)}" target="_blank" rel="noreferrer">${esc(a.title)} ↗</a>`:esc(a.title)}</strong><br>${esc(r.pages)}<br><small>${esc(a.detail)}</small></p>`;}).join('')}</details>`;}
function moduleDone(mi){return tierLessons(mi).filter(({i})=>state.done.includes(`${mi}-${i}`)).length;}
function learn(){
 const m=modules[activeModule],done=moduleDone(activeModule),next=nextLesson(modules,state.done,state.tier);
 const badges=[[1,'First bite'],[9,'Cheese explorer'],[27,'27-lesson club']];
 return `<div class="page-title"><div><div class="eyebrow">YOUR CHEESE ADVENTURE</div><h1>A little better.<br>A little cheesier.</h1><p>${lessonCount} lessons. Nine worlds of cheese. A deeper way to study.</p></div><span class="edition">THE<br>CHEESE<br>CURIOUS<br><b>CLUB / 03</b></span></div>
 <div class="study-tiers" role="group" aria-label="Study level"><button data-tier="foundation" aria-pressed="${state.tier==='foundation'}">Foundations <small>27 short lessons</small></button><button data-tier="ccp" aria-pressed="${state.tier==='ccp'}">CCP study <small>18 applied lessons</small></button></div><p class="course-hint">${state.tier==='ccp'?'Cases, calculations and sensory reasoning. Start any unit without repeating the foundations.':'Build your vocabulary, then move into applied CCP study.'}</p><div class="daily-strip">${icon('fire')}<span><strong>${state.days.includes(today())?'Daily goal complete!':'Your daily goal: one lesson'}</strong><small>${streak()} day streak · ${state.done.length} / ${lessonCount} lessons complete</small></span>${next?`<button class="text-button" data-lesson="${next}">Continue ${icon('arrow')}</button>`:icon('check')}</div>
 <div class="dashboard"><section><div class="chapter"><div><span class="eyebrow">UNIT ${String(activeModule+1).padStart(2,'0')} OF 09</span><h2>${m.title}</h2><p>${m.intro}</p><span class="chapter-count">${done} / ${tierLessons(activeModule).length} lessons complete ${done===tierLessons(activeModule).length?'· UNIT COMPLETE':''}</span></div>${mascot}</div>
 <div class="lesson-heading"><h3>${done===tierLessons(activeModule).length?'A delicious achievement':'Follow your curiosity'}</h3><span>${state.tier==='ccp'?'6–10':'2–4'} MIN / LESSON</span></div>
 <p class="domain-note">${state.tier==='ccp'?`ACS domains ${domainMap[activeModule].ids.join(', ')} · ${domainMap[activeModule].label}<br><small>Your study timeline: ${domainMap[activeModule].month}</small>`:''}</p><div class="learning-path">${tierLessons(activeModule).map(({l,i},position)=>{
 const id=`${activeModule}-${i}`,completed=state.done.includes(id),locked=!completed&&position>0&&!state.done.includes(`${activeModule}-${tierLessons(activeModule)[position-1].i}`);
 return `<div class="path-stop stop-${position}"><button class="path-node ${completed?'completed':locked?'locked':'ready'}" data-lesson="${id}" ${locked?'disabled':''} aria-label="${esc(l.title)}${completed?', completed':locked?', locked':''}" ${!locked&&!completed?'aria-current="step"':''}>${icon(completed?'check':locked?'lock':m.icon)}</button><div class="path-caption"><small>LESSON ${position+1}${completed?' · COMPLETE':''}</small><strong>${l.title}</strong><span>${locked?'Finish the previous lesson':completed?(state.best[id]===100?'Perfect lesson · revisit':'Practice again'):'Start · +20 XP'}</span></div></div>`;
 }).join('')}<div class="unit-medal ${done===tierLessons(activeModule).length?'earned':''}">${icon('star')}<span>${done===tierLessons(activeModule).length?'Unit mastered':'Complete this path to earn your unit badge'}</span></div></div>
 <div class="course-heading"><h3>Choose your next world</h3><span>9 SUBJECT AREAS</span></div><p class="course-hint">Each unit starts open. Lessons unlock as you go.</p><div class="module-list">${modules.map((v,i)=>`<button data-module="${i}" class="module ${i===activeModule?'selected':''}"><span class="module-number">${String(i+1).padStart(2,'0')}</span><span>${v.topic}<small>${moduleDone(i)} / ${tierLessons(i).length} complete</small></span>${icon(moduleDone(i)===tierLessons(i).length?'check':'arrow')}</button>`).join('')}</div>
 <details class="course-sources"><summary>About this course & sources</summary><p>Original practice informed by supplied ACS study resources and inspired by the Academy of Cheese Associate outline. This is not the official syllabus, exam bank, MPM or tasting model. Study those models and the complete 25-cheese list with the Academy’s course materials.</p><p>Advanced lessons cite the supplied Murray’s guide, ACS Body of Knowledge, lexicon and primary references. Historical notes are qualified; this is not a complete CCP preparation course or an official question bank. Source PDFs are not redistributed. Sources for this unit:</p>${m.sources.map(a=>`<a href="${a.url}" target="_blank" rel="noreferrer">${a.label} ↗</a>`).join('')}</details></section>
 <aside class="right-rail"><div class="daily"><span class="eyebrow">SMALL STEPS, GOOD HABITS</span><h3>Your daily slice</h3><div class="goal-ring"><span>${state.days.includes(today())?'1':'0'}<small>/ 1 lesson</small></span></div><p>${state.days.includes(today())?'You showed up. That counts.':'A few minutes today. More confidence tomorrow.'}</p><div class="goal-bottom">${icon('star')} ${state.xp} lifetime XP</div></div><div class="badge-shelf"><h3>Little wins</h3>${badges.map(([n,t])=>`<div class="achievement ${state.done.length>=n?'earned':''}">${icon('star')}<span>${t}<small>${state.done.length>=n?'Earned':`${n} ${n===1?'lesson':'lessons'}`}</small></span></div>`).join('')}</div><div class="tasting-prompt"><span class="eyebrow">TRY IT IN REAL LIFE</span>${icon('cheese','large-icon')}<h3>Meet your next cheese.</h3><p>Put your new vocabulary to work in a tasting note.</p><button class="text-button" data-view="journal">Open tasting journal ${icon('arrow')}</button></div><p class="local-note">Progress is saved in this browser.</p></aside></div>`;
}
function reviewQuestions(){return state.missed.map(key=>{const [m,l,q]=key.split('-').map(Number);return {key,data:modules[m]?.lessons[l]?.questions[q]};}).filter(q=>q.data);}
function practice(){const list=reviewQuestions();return `<div class="eyebrow">MAKE IT STICK</div><h1>A second helping.</h1><p>A quick refresher today helps tomorrow’s knowledge stick.</p><div class="practice-banner">${icon('star','large-icon')}<div><h2>${list.length?`${list.length} questions to revisit`:'Your mistakes are all cleared!'}</h2><p>${list.length?'You’ve found your next learning opportunity.':`Keep your memory fresh with a five-question mix from your selected ${state.tier==='ccp'?'CCP study':'Foundations'} tier.`}</p></div><button class="primary" id="${list.length?'review':'mix'}">${list.length?'Practice mistakes':'Daily mix'}</button></div>${list.length?'<button class="text-button" id="mix">Try a daily mix instead →</button>':''}<div class="lesson-heading"><h3>Revisit a lesson</h3><span>+5 XP PER REPLAY</span></div><div class="module-list">${modules.flatMap((m,mi)=>m.lessons.filter((l,li)=>state.done.includes(`${mi}-${li}`)).map(l=>{const li=m.lessons.indexOf(l);return `<button class="module" data-lesson="${mi}-${li}">${icon('check')}<span>${l.title}<small>${m.topic}</small></span>${icon('arrow')}</button>`;})).join('')||'<p>Finish your first lesson to build your practice library.</p>'}</div>`;}
function journal(){return `<div class="eyebrow">YOUR TASTING NOTEBOOK</div><h1>Remember every bite.</h1><p>No perfect vocabulary needed. Start with what you notice.</p><div class="journal-layout"><form id="note-form"><label>Cheese name<input name="cheese" placeholder="e.g. A mature farmhouse Cheddar" maxlength="120" required></label><div class="form-row"><label>Milk<select name="milk"><option>Not sure yet</option>Cow</option>Goat</option>Sheep</option>Buffalo</option>Mixed</option></select></label><label>Tasted on<input name="date" type="date" value="${today()}" required></label></div><label>Look & smell<textarea name="aroma" placeholder="The rind, the colour, that first aroma…" maxlength="1500"></textarea></label><label>Texture & flavour<textarea name="flavour" placeholder="Creamy, crumbly, nutty, tangy? Your words belong here." maxlength="1500" required></textarea></label><label>Your enjoyment<select name="rating"><option value="5">5 / 5 — Would absolutely taste again</option><option value="4">4 / 5 — Really enjoyed it</option><option value="3">3 / 5 — Interesting</option><option value="2">2 / 5 — Not quite for me</option><option value="1">1 / 5 — One taste was enough</option></select></label><button class="primary" type="submit">Save tasting note ${icon('arrow')}</button><small class="local-note">Saved in this browser. No account required.</small></form><section class="notes"><h3>Your collection <span>${state.notes.length}</span></h3>${state.notes.length?state.notes.slice().reverse().map(n=>`<article class="note"><span class="eyebrow">${esc(n.date)} · ${esc(n.milk)} MILK</span><h2>${esc(n.cheese)}</h2><span class="rating">${esc(n.rating)} / 5</span><p>${esc(n.aroma)}</p><p>${esc(n.flavour)}</p><button class="text-button delete-note" data-delete="${esc(n.id)}">Delete note</button></article>`).join(''):`<div class="empty">${icon('journal','large-icon')}<h3>Your first taste starts a story.</h3><p>Add a note to begin your own cheese collection.</p></div>`}</section></div>`;}
function bind(){document.querySelectorAll('[data-tier]').forEach(b=>b.onclick=()=>{state.tier=b.dataset.tier;save();render();});document.querySelector('.brand')?.addEventListener('click',e=>{e.preventDefault();view='learn';render();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render();window.scrollTo(0,0);});document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>{activeModule=Number(b.dataset.module);render();window.scrollTo(0,0);});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>start(b.dataset.lesson));document.querySelector('#review')?.addEventListener('click',()=>{const questions=reviewQuestions();if(!questions.length)return;session=createSession(questions,{review:true});render();});document.querySelector('#mix')?.addEventListener('click',()=>{let pool=modules.flatMap((m,mi)=>m.lessons.flatMap((l,li)=>inTier(l,state.tier)?l.questions.map((data,i)=>({key:`${mi}-${li}-${i}`,data})):[]));for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}session=createSession(pool.slice(0,5),{review:true,mix:true});render();});document.querySelector('#note-form')?.addEventListener('submit',e=>{e.preventDefault();let values=Object.fromEntries(new FormData(e.target));if(!values.cheese.trim()||!values.flavour.trim())return;state.notes.push({...values,id:crypto.randomUUID()});save();notice='Tasting note saved.';render();});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Delete this tasting note?')){state.notes=state.notes.filter(n=>n.id!==b.dataset.delete);save();render();}});}
function start(id){const [mi,li]=id.split('-').map(Number),lesson=modules[mi]?.lessons[li];if(!lesson)return;state.tier=lesson.level==='ccp'?'ccp':'foundation';save();activeModule=mi;session=createSession(lesson.questions.map((data,i)=>({key:`${id}-${i}`,data})),{id,lesson,phase:'read',readStep:0});render();window.scrollTo(0,0);}
function answerText(q){return (Array.isArray(q[2])?q[2]:[q[2]]).map(i=>q[1][i]).join(kind(q)==='order'?' → ':' + ');}
function renderLesson(){
 const s=session,current=s.questions[s.step],q=current?.data,type=q?kind(q):'choice';
 if(q&&type!=='choice'&&!Array.isArray(s.selected))s.selected=[];
 const currentUnitNext=s.id?modules[activeModule].lessons.findIndex((l,i)=>inTier(l,state.tier)&&!state.done.includes(`${activeModule}-${i}`)):-1;
 const next=currentUnitNext>=0?`${activeModule}-${currentUnitNext}`:nextLesson(modules,state.done,state.tier);
 root.innerHTML=`<div class="lesson-screen"><header class="lesson-header"><button class="close" aria-label="Exit lesson">×</button><div class="progress-track" role="progressbar" aria-label="Questions learned" aria-valuemin="0" aria-valuemax="${s.total}" aria-valuenow="${s.resolved.length}"><i style="width:${s.resolved.length/s.total*100}%"></i></div><span>${s.phase==='done'?'COMPLETE':s.phase==='read'?'QUICK READ':`${s.resolved.length} / ${s.total}`}</span></header><main class="lesson-content">
 ${s.phase==='read'?`<span class="eyebrow">A LITTLE KNOWLEDGE FIRST</span><h1 tabindex="-1">${s.lesson.title}</h1>${s.lesson.sections?`<div class="read-position">STUDY CARD ${s.readStep+1} / ${s.lesson.sections.length}</div><h2>${esc(s.lesson.sections[s.readStep].title)}</h2><p class="reading">${esc(s.lesson.sections[s.readStep].body)}</p>${s.readStep===0?`<ul class="objectives">${s.lesson.objectives.map(o=>`<li>${esc(o)}</li>`).join('')}</ul>`:''}${references(s.lesson.references)}`:`<div class="reading-art">${mascot}</div><p class="reading">${s.lesson.read}</p>`}<p class="read-hint">${s.total} quick challenges. Mistakes are part of the lesson—you’ll get another try.</p><button class="primary" id="begin">${s.lesson.sections&&s.readStep<s.lesson.sections.length-1?'Next study card':'Let’s try it'} ${icon('arrow')}</button>${s.readStep>0?'<button class="text-button" id="read-back">Previous study card</button>':''}`:
 s.phase==='done'?`<div class="completion"><div class="celebration">${mascot}<span class="spark spark-one">✦</span><span class="spark spark-two">✦</span><span class="spark spark-three">✦</span></div><span class="eyebrow">${s.correct===s.total?'PERFECT FIRST ROUND':'YOU STUCK WITH IT'}</span><h1 tabindex="-1">${s.review?'Fresh in your memory!':'Lesson complete!'}</h1><p>${s.correct} of ${s.total} right on your first try.${s.correct<s.total?' You worked through every mistake.':' That’s some sharp thinking.'}</p><div class="completion-stats"><div><b>+${s.reward}</b><span>XP EARNED</span></div><div><b>${Math.round(s.correct/s.total*100)}%</b><span>FIRST-TRY ACCURACY</span></div><div><b>${s.bestCombo}</b><span>BEST COMBO</span></div></div>${s.unitFinished?'<p class="unit-win">Unit complete! Another world of cheese explored.</p>':''}<p>${streak()} day streak · Daily goal complete</p>${next?`<button class="primary" id="next-lesson">Next: ${modules[next.split('-')[0]].lessons[next.split('-')[1]].title} ${icon('arrow')}</button>`:''}<button class="${next?'secondary':'primary'}" id="finish">Back to your path</button></div>`:
 `<div class="exercise-meta"><span class="eyebrow">${current.retry?'LET’S TRY THAT AGAIN':type==='order'?'PUT IT IN ORDER':type==='multi'?'SELECT ALL THAT FIT':'CHOOSE ONE ANSWER'}</span><span class="combo">${s.combo>=2?`${s.combo} in a row!`:''}</span></div><h1 class="question" tabindex="-1">${q[0]}</h1><p class="exercise-hint">${type==='order'?'Tap the steps in order. Tap a chosen step to remove it.':type==='multi'?'Select every correct answer.':'Pick the answer that fits best.'}</p>${type==='order'?`<div class="order-slots" aria-label="Your selected order">${s.selected.length?s.selected.map((v,i)=>`<button class="order-chip" data-remove="${v}" ${s.checked?'disabled':''}>${i+1}. ${q[1][v]} <span aria-hidden="true">×</span></button>`).join(''):'<span>Your sequence will appear here</span>'}</div>`:''}<div class="answers">${q[1].map((a,i)=>{const chosen=type==='choice'?s.selected===i:s.selected.includes(i);return `<button class="answer ${chosen?'selected':''} ${s.checked&&type!=='order'&&(Array.isArray(q[2])?q[2].includes(i):q[2]===i)?'correct':''} ${s.checked&&chosen&&!s.right?'wrong':''}" data-answer="${i}" ${s.checked||type==='order'&&chosen?'disabled':''} aria-pressed="${chosen}"><span>${type==='multi'?(chosen?'✓':'+'):String.fromCharCode(65+i)}</span>${a}</button>`;}).join('')}</div><div class="feedback ${s.checked?(s.right?'positive':'negative'):''}" role="status" aria-live="polite">${s.checked?`<h3>${s.right?(current.retry?'You’ve got it now!':s.combo>=3?'You’re on a roll!':'Nicely done!'):'Not quite. You’ll see this again.'}</h3>${!s.right?`<p><strong>${answerText(q)}</strong></p>`:''}<p>${q[3]}</p>${q[5]?.why?`<p class="why"><strong>Why the alternatives miss</strong><br>${esc(q[5].why)}</p>`:''}${references(modules[current.key.split('-')[0]]?.lessons[current.key.split('-')[1]]?.references)}`:''}</div><button class="primary" id="check" ${!s.checked&&!canCheck(q,s.selected)?'disabled':''}>${s.checked?(s.step===s.questions.length-1?'Finish lesson':'Continue'):'Check answer'} ${icon('arrow')}</button>${!s.review?'<button class="text-button hint-toggle" id="hint">Read the lesson again</button><div id="hint-copy" hidden></div>':''}`}</main></div>`;
 document.querySelector('.close').onclick=()=>{if(s.phase==='done'||confirm('Leave this lesson? XP and completion are awarded when you finish.')){session=null;render();}};
 document.querySelector('#begin')?.addEventListener('click',()=>{if(s.lesson.sections&&s.readStep<s.lesson.sections.length-1)s.readStep++;else s.phase='quiz';render();document.querySelector('h1')?.focus();});
 document.querySelector('#read-back')?.addEventListener('click',()=>{s.readStep--;render();});
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.answer);if(type==='choice')s.selected=i;else if(type==='order')s.selected.push(i);else s.selected=s.selected.includes(i)?s.selected.filter(v=>v!==i):[...s.selected,i];render();document.querySelector(`[data-answer="${i}"]`)?.focus();});
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{s.selected=s.selected.filter(v=>v!==Number(b.dataset.remove));render();});
 document.querySelector('#check')?.addEventListener('click',()=>{if(s.checked){if(advance(s))complete();render();document.querySelector('h1')?.focus();}else{if(!canCheck(q,s.selected))return;const right=checkAttempt(s);if(right)state.missed=state.missed.filter(k=>k!==current.key);else if(!state.missed.includes(current.key))state.missed.push(current.key);save();render();document.querySelector('#check')?.focus();}});
 document.querySelector('#hint')?.addEventListener('click',()=>{const hint=document.querySelector('#hint-copy');hint.hidden=!hint.hidden;hint.textContent=s.lesson.read;});
 document.querySelector('#finish')?.addEventListener('click',()=>{session=null;view='learn';render();window.scrollTo(0,0);});
 document.querySelector('#next-lesson')?.addEventListener('click',()=>start(next));
}
function complete(){const s=session,first=!s.review&&!state.done.includes(s.id);s.reward=first?20+(s.correct===s.total?5:0):5;if(first)state.done.push(s.id);if(!s.review){state.best[s.id]=Math.max(Number(state.best[s.id])||0,Math.round(s.correct/s.total*100));state.lastLesson=s.id;s.unitFinished=first&&moduleDone(activeModule)===tierLessons(activeModule).length;}state.xp+=s.reward;if(!state.days.includes(today()))state.days.push(today());s.phase='done';save();}
document.addEventListener('keydown',e=>{if(!session||e.repeat||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='Enter'&&!['BUTTON','A','SUMMARY'].includes(e.target.tagName)){const b=document.querySelector('#check:not(:disabled),#begin,#next-lesson,#finish');if(b){e.preventDefault();b.click();}}});
render();
